 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    done = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in done:
                continue
            rr, cc = h - 1 - r, w - 1 - c
            done.add((r, c))
            done.add((rr, cc))
            if grid[rr][cc] != 3:
                out[r][c] = grid[rr][cc]
                out[rr][cc] = grid[r][c] if grid[r][c] != 3 else grid[rr][cc]
            else:
                # If a marked cell and its rotational counterpart are both masked,
                # infer their shared value from the nearest unmasked local clues.
                clues = []
                for ar, ac in ((r, c), (rr, cc)):
                    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        nr, nc = ar + dr, ac + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 3:
                            clues.append(grid[nr][nc])
                value = Counter(clues).most_common(1)[0][0] if clues else 0
                out[r][c] = out[rr][cc] = value
    return out


